contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount, address recipient) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(recipient != address(0));
        require(address(this).balance >= depositAmount);

        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint256 beforeRecipient = recipient.balance;
        uint256 beforeC = address(c).balance;

        c.migrateTo(recipient); if (__ESBMC_reverted()) return;

        assert(address(c).balance == 0 && recipient.balance - beforeRecipient == beforeC);
    }

    receive() external payable {}
}

